import{_ as a,o as r,c as o,an as t}from"./chunks/framework.OQmPwz3_.js";const h=JSON.parse('{"title":"Hardware Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/hardware.md","filePath":"configuration/hardware.md","lastUpdated":null}'),n={name:"configuration/hardware.md"};function i(c,e,d,s,l,g){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="Hardware-Configuration" tabindex="-1">Hardware Configuration <a class="header-anchor" href="#Hardware-Configuration" aria-label="Permalink to &quot;Hardware Configuration {#Hardware-Configuration}&quot;">​</a></h1><p>Legate chooses the hardware configuration automatically. Set these environment variables before starting Julia to override it:</p><ul><li><p><code>LEGATE_SHOW_CONFIG</code> : When set to 1, the Legate config is printed to stdout</p></li><li><p><code>LEGATE_AUTO_CONFIG</code>: When set to 1, Legate will automatically choose the hardware configuration</p></li><li><p><code>LEGATE_CONFIG</code>: A string representing the hardware configuration to set</p></li></ul><p>Set <code>export LEGATE_SHOW_CONFIG=1</code> to print the hardware configuration when Legate starts.</p><p>To configure hardware manually, set <code>export LEGATE_AUTO_CONFIG=0</code>, then set <code>LEGATE_CONFIG</code>, for example <code>export LEGATE_CONFIG=&quot;--gpus 1 --cpus 10&quot;</code>. Keep the default memory configuration and set the <code>--gpus</code> and <code>--cpus</code> flags to limit the resources Legate reserves. See the <a href="https://docs.nvidia.com/legate/latest/usage.html#resource-allocation" target="_blank" rel="noreferrer">NVIDIA Legate documentation</a> for more options.</p><p>The same <code>LEGATE_CONFIG</code> string can carry logging / profiling flags (for example <code>--logging legate=debug --log-to-file</code>). Those are covered under <a href="/cuNumeric.jl/stable/debugging#trace-legate-runtime-work">Debugging</a>, including how they pair with <a href="/cuNumeric.jl/stable/api_preferences#task-scope-names">CNPreferences</a> task-scope naming.</p><p>The benchmark harness (<code>benchmark/run.jl</code> via <code>run_benchmark.sh</code>) sets <code>LEGATE_CONFIG</code> from <code>--gpus</code> / <code>--cpus</code> before each worker starts. See the <a href="https://github.com/JuliaLegate/benchmarking" target="_blank" rel="noreferrer">benchmarking repository</a>.</p>',7)])])}const p=a(n,[["render",i]]);export{h as __pageData,p as default};
